function factorialWithStack(n) {
  const stack = [];
  let current = n;
  while (current > 1) {
    stack.push(current);
    current -= 1;
  }
  let result = 1;
  while (stack.length > 0) {
    result *= stack.pop();
  }
  return result;
}

console.log(factorialWithStack(5));

